INSERT INTO squad_entries VALUES(10,1,11,NULL,'FB','OWNED','0001101128000370014X00144',6.459999999999999965,'season','RB 8선발 704분 평균 6.46 · 피크 7.1 (RDM 6.84보다 낮음 — 난도 미보정)','fb_wingback','Balanced',0.8319999999999999619,'appearances measured (2026-07-21 슬롯 추가)','OWNED — 표본 n=1 긴급배치 / 🔄 **[2026-07-31 obs#104]** 그리드를 **1경기 → 8선발 전수 집계**로 교체(557 히트포인트, `player_match_grids` 8행 신규 적재). 옛 값은 긴급 출전 1경기 표본이었고 정의 없는 밴드 `r1`을 쓰고 있었다. ⚠️ **자기진영 질량이 1.2 → 2.4로 배가**됐다 — 1경기 표본이 그의 전진 성향을 과대평가하고 있었다. 적합: att_wb/Support .890→.854 · wingback/Support .808→.795 · wingback/Balanced .761→**.832**. 처방을 같은 역할 안에서 Support → **Balanced**로 옮겼다(전방 질량 둘 다 0.30이라 C2 불변, 뱅크는 1.2→1.6으로 rest-defense 성격에 더 부합). 옛↔신 그리드 코사인 .904.',22,NULL,NULL,NULL);
INSERT INTO squad_entries VALUES(11,1,10,NULL,'WM','OWNED','001370126X003770024600011',7.080000000000000071,'season','RM 21경기 평균 7.08 · 피크 8.7','wm_wideplm','Attack',0.7610000000000000097,'appearances measured','OWNED / [2026-08-24 NULL fit 백필] 최초 시드 행(squad_entries.id≤17 · source=''appearances measured'' · 날짜 스탬프 없음)이라 fit 파이프라인 도입 이전에 만들어져 값이 비어 있었다 — 판단에 의한 NULL이 아니라 누락이다. core.kernel 재산출값을 적재: wm_wideplm/Attack 0.761. 근거: player_duties(id=14)가 값까지 명시: 「wm_wideplm/Attack 커널이 실측 .51과 정확히 겹치고 적합 1위(.761)」.',50,NULL,NULL,'RM');
INSERT INTO squad_entries VALUES(12,1,10,NULL,'DM','OWNED','101231147402778027XX00335',7.870000000000000106,'season','피벗우측 7경기 평균 7.87 (season pivot-right, n=7)','dm_dlp','Roaming',0.7169999999999999707,'appearances measured (2026-07-21 슬롯 추가)','OWNED — 딥롤 3경기, RDM 전용(LDM 0.44) [2026-08-21 정정] fit_sim 0.878 → 0.717. 저장값이 커널 최대(0.717)를 넘어 argmax 규칙으로는 산출 불가능한 값이었다 — 구 커널(obs#93·94 교체 이전) 또는 타 기하 산출 잔재로 판단하고 scripts/check_fit_drift.py 재산출값으로 교체했다(사용자 지시).',51,NULL,NULL,NULL);
