INSERT INTO squad_entries VALUES(22,2,13,NULL,'WM','OWNED','46465487X9347552535401121',6.900000000000000355,'full2526','CAM 34경기 평균 6.9 (measured:season:full2526)','wm_insidefwd','Balanced',0.6450000000000000177,'player_role_map(kind=measured) 파생 — 2026-08-11 팀 축 배선',unistr('실측 그리드는 원 수집 그대로. 평점은 rationale 본문 파싱값이라 구조화 필드가 아니다.\u000a⛔⭐ **[2026-08-19 역할군 불일치 해소]** 이 행은 `slot_type`=WM인데 저장된 fit이 **`cam_playmaker`/Roaming 0.715(= CAM군)** 이었다 — **FC26에서 WM 슬롯에 배정할 수 없는 역할**이고, CHE 5-4-1에는 CAM 슬롯 자체가 없다. 슬롯 유형 내부에서만 재산출: **`wm_insidefwd`/Balanced 0.645** (최적 RM). 좌우 분해: LM=0.522 · RM=0.645. ⚠️ 종전 값은 **역할군을 무시한 전역 argmax**로 보인다 — obs#254 ⑸의 게이트 결손이 이 4건을 방치했다.'),8,'Aston Villa (25/26)','⚠️ 첼시 공식전 0경기 — 그리드 전량이 빌라 시절(PL 37 · EL 12 · FA 2)이고 에메리 전술의 산물이다. 알론소 첼시에서 같은 위치를 쓴다는 근거가 아니다.',NULL);
INSERT INTO squad_entries VALUES(23,2,31,NULL,'GK','OWNED','0000000000000000020000X20',6.849999999999999645,'alonso2627','알론소 백3 2경기 151분 평균 6.85','gk_goalkeeper','Balanced',0.955999999999999961,'player_role_map(kind=measured) 파생 — 2026-08-11 팀 축 배선',unistr('실측 그리드는 원 수집 그대로. 평점은 rationale 본문 파싱값이라 구조화 필드가 아니다.\u000a⭐⭐ **[2026-08-19 알론소 실측 전환]** 그리드를 **25/26 마레스카·로즈니어 체제 → 알론소 26/27 체제**로 교체했다(불변규칙 7의 팀축 혼입이 처음 해소됐다). 출처: **알론소 백3 2경기 집계**(밀란·조호르·소시에다드 중 유효 표본, `core.aggregate`). 표본 2경기 151분 · 평균 평점 6.85 · 실측 툴x **51.2** · 툴y 11.85. 3-4-2-1 `GK`(x=50) 커널 최적 = `gk_goalkeeper`/Balanced **0.956**. ⚠️ 표본은 프리시즌 친선이고 공식전 0경기다(첫 경기 08-24 풀럼).'),0,'Chelsea (알론소 26/27)','⚠️ 프리시즌 친선 2경기 표본 · 공식전 0경기(08-24 풀럼 첫 경기)',NULL);
