INSERT INTO squad_entries VALUES(59,1,28,'일링주니어','WM','OWNED','001361017X001271013800023',6.419999999999999929,'full2526','RM 9경기 평균 6.42 (measured:season:full2526)','wm_winger','Balanced',0.7800000000000000266,NULL,NULL,79,'임대처(Championship·Serie A)','⚠️ 빌라 공식전 0경기 — 그리드 전량이 임대 시절(Championship 14 · Serie A 1, 2025-09~2026-02). ⚠️ 챔피언십은 PL과 리그 수준이 다르다.',NULL);
INSERT INTO squad_entries VALUES(60,1,78,'루헤리','FB','CONFIRMED','310009200081000X300052100',6.719999999999999752,'full2526','LB 45경기 평균 6.72 (measured:season:full2526)','fb_att_wb','Support',0.931000000000000049,NULL,unistr('\u000a⭐ **[2026-08-19] 빌라 공식 발표로 CONFIRMED 확정.** 이 행은 발표 이전에 생성돼 있었고, 오늘 `transfer_targets`(id=141)를\u000aHIGH → CONFIRMED로 갱신해 정합을 맞췄다. ⚠️ 그리드는 **아틀레티코 45경기** 실측이며 빌라 공식전 0경기다(불변규칙 7).\u000a**[2026-08-19] 뎁스차트 위치 이동 — sort_order 80 → 23**(사용자 판단: 「보유 그룹 안, 기존 선발 뒤」).\u000a종전 80은 **FB 후보 맨 끝**이라 시즌 임대로 나가는 네델코비치(73)보다도 뒤였다 — 공식 영입 후의 자리가 아니다.\u000a23은 마첸(20)·캐시(21)·보가르드(22) 뒤, 네델코비치(73) 앞이다. ⇒ 히트맵·XI의 **기본 선발은 마첸·캐시 그대로 유지**되고\u000a루헤리는 드롭다운 4번째로 올라온다. ⚠️ 다른 CONFIRMED 영입(시세 8·만잠비 11·고메스 12·가르나초 15)은 그룹 **선두**에 놓였으나,\u000a이 건은 「영입했지만 아직 주전으로 확정하지 않았다」는 판단이라 관례와 의도적으로 다르다.\u000a⭐ **[2026-08-19 22시 등번호 확정]** **No.13** — avfc.co.uk `/news/2026/august/19/signing-ruggeri-squad-number-confirmed/`. 아틀레티코 No.3 · 아탈란타 No.22였다. ⇒ 21시 회차가 「이적료·계약 연수·등번호 전부 미공표」로 남긴 결손 중 **등번호가 해소**됐다. ⚠️ **이적료·계약 연수는 여전히 미공표**이고 금액 3분기 충돌(€26.5m ↔ €30m/2031 ↔ ~€20m)도 미해소다.'),23,'Atlético Madrid','⚠️ 빌라 공식전 0경기 — 그리드 전량이 아틀레티코 마드리드 시절(25/26 45분+ 45경기)이다. 적합값은 "아틀레티코에서 하던 일"의 적합이며 에메리 전술에서 같은 위치를 쓴다는 근거가 아니다(obs#157·#158). ⭐ 같은 선수가 팀을 옮기자 좌우 위치가 17~18단위 움직인 사례가 둘 있다(베일리·게상, obs#158).','LB');
INSERT INTO squad_entries VALUES(61,3,85,'아라우호','CB','CONFIRMED','000000011101043001X300379',7.0,'iraola2627','이라올라 프리시즌 1경기 45분 평균 7.0','cb_bpd','Build-Up',0.8389999999999999681,NULL,unistr('\u000a⭐⭐ **[2026-08-19 이라올라 실측 전환]** 그리드를 **25/26 슬롯 체제 → 이라올라 26/27**로 교체했다(불변규칙 7 팀축 혼입 해소). 출처: 프리시즌 4-2-3-1 **1경기 집계**(`core.aggregate`), 45분 · 평균 평점 7.0 · 실측 툴x **72.05** · 툴y 27.58 · lineup_pos=D. 슬롯 `CB`(x=68, 실측 이동 앵커) 커널 최적 = `cb_bpd`/Build-Up **0.839**. ⚠️ 프리시즌 친선 표본이고 공식전 0경기다(08-23 뉴캐슬 첫 경기).'),6,'Liverpool (이라올라 26/27)','⚠️ 프리시즌 친선 1경기 · 공식전 0경기(08-23 뉴캐슬 첫 경기)','RCB');
INSERT INTO squad_entries VALUES(63,2,80,'차바리아','FB','CONFIRMED','510009210093100X510053100',6.799999999999999823,'full2526','LB 39경기 평균 6.80 (measured:season:full2526)','fb_att_wb','Support',0.8900000000000000133,'SofaScore 25/26 전수 55경기 중 45분+ 39경기 ; 구단 공식 https://www.chelseafc.com/en/news/article/pep-chavarria-signs-for-chelsea','39/39 전 경기 좌측 우세(좌2컬럼 0.93 · 우2 0.00)라 좌우 혼입 없음.',5,'Rayo Vallecano (25/26)','⚠️ 첼시 공식전 0경기 — 그리드 전량이 **라요 바예카노 시절**(25/26 45분+ 39경기)이다. 적합값은 "라요에서 하던 일"의 적합이며 알론소 전술에서 같은 위치를 쓴다는 근거가 아니다(obs#157·#158). ⭐ 같은 선수가 팀을 옮기자 좌우 위치가 17~18단위 움직인 사례가 둘 있다(베일리·게상, obs#158). ⚠️ 알론소 체제는 공식전 0경기다(첫 경기 8/24 풀럼). ⚠️ 포지션은 **하토의 백업·경쟁**이며 주전 결손 보강이 아니다.',NULL);
INSERT INTO squad_entries VALUES(64,3,88,'무뇨스','WM','CONFIRMED','54123X5222422114211111100',7.030000000000000248,'full2526','좌측 23경기 평균 7.03 (measured:season:full2526)','wm_wideplm','Attack',0.7289999999999999814,'SofaScore player 1145642, 25/26 오사수나 클럽경기(라리가+코파) 45분+·히트포인트 15+ 34경기 중 좌측 23경기(1898분) 균등가중 ; 구단 공식 https://www.liverpoolfc.com/news/liverpool-agree-deal-sign-spain-forward-victor-munoz (2026-06-18)','⭐ **양 측면 자원이라 좌우를 분리했다**(obs#156 규약). 34경기 혼합으로 재면 LM .615로 급락하는데, 이는 좌 23·우 11이 섞여 그리드가 중앙으로 뭉개지기 때문이다. 좌우 분리 후: **좌측 23경기 LM wm_wideplm/Attack .729** / 우측 11경기 RM wm_winger/Balanced .772. 주 표본(좌측, 2배 표본)을 행 값으로 채택했다.',11,'Osasuna (25/26)','⚠️ 리버풀 공식전 0경기 — 그리드 전량이 **오사수나 시절**(25/26 45분+ 34경기 중 좌측 23경기)이다. 적합값은 "오사수나에서 하던 일"의 적합이며 이라올라 전술에서 같은 위치를 쓴다는 근거가 아니다(obs#157·#158). ⭐⭐ **우측으로 쓰면 값이 달라진다** — 우측 11경기만 재면 **RM wm_winger/Balanced .772**로 좌측(.729)보다 높다. 살라 이탈로 리버풀의 결손 칸이 우측인 점을 감안하면 이 행 하나로 판단하지 말 것. ⚠️ 이라올라 체제는 공식전 0경기다(첫 경기 8/23 뉴캐슬 원정). ⚠️ 표본은 라리가 중위권 팀의 것이다 — 리그·팀 수준 보정 없음.',NULL);
INSERT INTO squad_entries VALUES(65,3,89,'자케','CB','CONFIRMED','0010000101101X11126101331',8.199999999999999289,'iraola2627','이라올라 프리시즌 1경기 45분 평균 8.2','cb_bpd','Aggressive',0.8269999999999999574,'SofaScore player 1445625, 25/26 렌 클럽경기(리그1+쿠프드프랑스) 45분+·히트포인트 15+ 21경기 중 우측 14경기(1239분) 균등가중 ; 구단 공식 https://www.liverpoolfc.com/news/liverpool-complete-signing-jeremy-jacquet (2026-07-01)',unistr('⭐ **좌우 분리 적용**(obs#156). 21경기 혼합 RCB .838 → 우측 14경기만 **RCB cb_bpd/Aggressive .903**. 좌측 7경기만 재면 LCB .850이라 **양쪽 다 가능하나 우측이 주 표본이자 argmax**다. 표본이 렌 소속 21경기로 충분(1853분).\u000a⭐⭐ **[2026-08-19 이라올라 실측 전환]** 그리드를 **25/26 슬롯 체제 → 이라올라 26/27**로 교체했다(불변규칙 7 팀축 혼입 해소). 출처: 프리시즌 4-2-3-1 **1경기 집계**(`core.aggregate`), 45분 · 평균 평점 8.2 · 실측 툴x **62.4** · 툴y 35.92 · lineup_pos=D. 슬롯 `CB`(x=68, 실측 이동 앵커) 커널 최적 = `cb_bpd`/Aggressive **0.827**. ⚠️ 프리시즌 친선 표본이고 공식전 0경기다(08-23 뉴캐슬 첫 경기).'),5,'Liverpool (이라올라 26/27)','⚠️ 프리시즌 친선 1경기 · 공식전 0경기(08-23 뉴캐슬 첫 경기)','RCB');
INSERT INTO squad_entries VALUES(66,1,30,'헤밍스','WM','OWNED','66111X4430X41009403004000',6.200000000000000177,'event:16260286','슈퍼컵 PSG전 90분 평점 6.2','wm_widemid','Support',0.7880000000000000337,'SofaScore event 16260286 — LAM 90분·히트포인트 51·평균위치 (58.11,73.31)','HIGH 원천 데이터 / MEDIUM 대표 역할 — 단일 공식전 표본',81,'Aston Villa (2026-27)','⚠️ 공식전 1경기. LM/LAM 대표 역할 확정 전 추가 표본 필요.',NULL);
INSERT INTO squad_entries VALUES(67,1,55,'만잠비','WM','CONFIRMED','35345X9578542261322300020',7.200000000000000177,'national','스위스 대표팀 12경기 평균 7.2','wm_wideplm','Attack',0.6520000000000000239,'transfer_targets id=122 LM 승격 (현재 스쿼드 정합성 수리)','CONFIRMED 영입은 squad_entries 승격이 규칙. LM 적합은 대표팀 전진 배치 표본.',16,'SC Freiburg + 스위스 대표팀','⚠️ 빌라 공식전 0경기 — 대표팀 표본은 포지션 혼입(CAM 선발 2경기뿐)이고 좌우 평균 산물이다(obs#156).',NULL);
INSERT INTO squad_entries VALUES(68,1,132,'스즈키','GK','CONFIRMED','0000000000000000010001X20',7.049999999999999823,'full2526','GK 29경기 평균 7.05 (파르마·일본대표 실측 · measured:season:full2526)','gk_goalkeeper','Defend',0.974999999999999978,'transfer_targets id=149 GK 승격 (2026-08-17) · prescriptions measured:season:full2526 · obs#220·#222·#223·#234',unistr('CONFIRMED 영입은 squad_entries 승격이 규칙. ⚠️ **양 구단 공식 발표는 여전히 0건이다**(2026-08-18 메인 세션이 avfc.co.uk 뉴스·parmacalcio1913.com/news 직접 파싱해 확인 — 빌라 최신은 FPL 프리뷰·글라드바흐전·일링 볼턴 임대, 파르마 최신은 로메로 영입·온드레이카 임대). ⇒ **DB에 못 박은 CONFIRMED 트리거(`avfc.co.uk 공식 발표`)는 미충족 상태이고, 이 승격은 사용자 지시에 따른 것이다.** 근거 상한: **메디컬 실시 확인**(Romano 1티어 08-17 07:21 UTC) + **개인 조건 5년 계약 합의**(Ornstein 1티어) + **£29.9m/€30m+€5m 구단 간 합의**(Sky UK 1티어 08-16) + **Moretto(2티어) ''완료''**. ⛔ **''here we go''는 이 건에 붙지 않았다** — 일부 매체 헤드라인의 HWG는 태그 전용(轉用)이다(obs#234·transfer-watch 기록). ⚠️ obs#233(오늘 다른 세션)이 **''신호 하나로 등급을 올렸다가 24시간 만에 뒤집힌''** 마르티네스 사례를 남겼다 — 다만 스즈키는 **메디컬 이후** 단계이고 PSG 결렬은 **메디컬 직전**이었다는 점에서 국면이 다르다. ⇒ **공식 발표가 확인되면 이 캐비앗을 해제하고, 반대로 결렬되면 이 행들을 되돌려야 한다.**\u000a⭐⭐ **[2026-08-19] 캐비앗 해제 — 빌라 공식 발표 확인.** avfc.co.uk `/news/2026/august/19/signing-villa-confirm-suzuki-signing/`\u000a(완전이적 명시). 위에 적힌 「CONFIRMED 트리거 미충족 · 사용자 지시에 따른 승격 · 결렬 시 되돌려야 한다」는 **더 이상 적용되지 않는다.**\u000a⚠️ 단 grid_caveat(파르마 딥블록 표본 · GK 커널 미변별)는 실측 한계이므로 **그대로 유효**하다.'),11,'Parma','⚠️ 빌라 공식전 0경기 — 그리드는 파르마 22경기 + 일본대표 7경기(45분+ · 히트맵 15pt+, 2602분)에서 나왔다. ⛔ GK는 커널 적합이 변별하지 못한다(obs#220, 측정 GK 5명 상호 코사인 ≥0.986) — 변별은 평균 위치다(tool_y 10.06으로 마르티네스 11.16보다 1.10 깊다). ⚠️ 파르마는 잔류권 딥블록이라 빌라의 높은 라인에서 같은 값이 재현된다는 근거가 아니다(불변규칙 7).',NULL);
INSERT INTO squad_entries VALUES(69,2,37,NULL,'CM','OWNED','323118X533577425743211100',NULL,NULL,NULL,'cm_b2b','Ball-Winning',0.830999999999999961,'[2026-08-19] 3-4-3 전환 신규 행 · core.kernel best_fit',unistr('⭐ **[2026-08-19] 3-4-3 전환 신규 행.** obs#58(1티어 premierleague.com)·team_tactic_setups id=8이 공통으로 지목한 「엔소+카이세도」 더블 피벗. 커널: LCM 1.710(제임스 조합 1.502, +0.208) — id=15 미해결 ⓑ 해소. 산출: `cm_b2b`/Ball-Winning **0.831** (x=40, slot_type=CM). ⚠️ 그리드는 **첼시 25/26 마레스카·로즈니어 체제** 표본이다(불변규칙 7) — 알론소 실측 0경기.\u000a⚠️ **[2026-08-19] LCM 2순위로 이동.** 이 행의 그리드는 **25/26 마레스카·로즈니어 체제**이고 알론소 백3 3경기에서 45분+ 출전이 없어 갱신하지 못했다(소시에다드전 28분). ⭐ obs#58(1티어)·id=8이 지목한 「엔소+카이세도」 피벗 가설은 **여전히 유효하나 알론소 실측으로 검증되지 않았다** — 개막 후 45분+ 표본이 쌓이면 재판정한다.'),5,NULL,NULL,'LCM');
INSERT INTO squad_entries VALUES(70,2,80,'차바리아','WM','CONFIRMED','510009210093100X510053100',NULL,NULL,NULL,'wm_widemid','Support',0.8299999999999999601,'[2026-08-19] 3-4-3 전환 신규 행 · core.kernel best_fit',unistr('⭐ **[2026-08-19] 3-4-3 전환 신규 행.** 3-4-3의 좌 윙백. FB .890 → WM .830(−.060)이나 3-4-3엔 FB 슬롯이 없다. ⚠️ LM .830 ↔ RM .021로 좌측 전용이라 pos_only 필수. 산출: `wm_widemid`/Support **0.83** (x=14, slot_type=WM). ⚠️ 그리드는 **첼시 25/26 마레스카·로즈니어 체제** 표본이다(불변규칙 7) — 알론소 실측 0경기.\u000a**[2026-08-19 3-4-2-1 뎁스 순서]** sort_order=5. 차바리아 — 팔레스트라 뒤 좌측 뎁스. 그리드는 라요 25/26이라 팀축이 다르다(불변규칙 7).'),5,'Rayo Vallecano (25/26)','⚠️ 첼시 공식전 0경기 — 그리드 전량이 **라요 바예카노 시절**(25/26 45분+ 39경기)이다. 적합값은 "라요에서 하던 일"의 적합이며 알론소 전술에서 같은 위치를 쓴다는 근거가 아니다(obs#157·#158). ⭐ 같은 선수가 팀을 옮기자 좌우 위치가 17~18단위 움직인 사례가 둘 있다(베일리·게상, obs#158). ⚠️ 알론소 체제는 공식전 0경기다(첫 경기 8/24 풀럼). ⚠️ 포지션은 **하토의 백업·경쟁**이며 주전 결손 보강이 아니다.','LM');
INSERT INTO squad_entries VALUES(71,2,32,NULL,'WM','OWNED','00123001490015X0014900135',NULL,NULL,NULL,'wm_widemid','Support',0.8609999999999999876,'[2026-08-19] 3-4-3 전환 신규 행 · core.kernel best_fit',unistr('⭐ **[2026-08-19] 3-4-3 전환 신규 행.** 3-4-3의 우 윙백. ⭐ WM .861 ≥ FB .859로 오히려 상승. ⚠️ RM .861 ↔ LM .033으로 우측 전용. 산출: `wm_widemid`/Support **0.861** (x=86, slot_type=WM). ⚠️ 그리드는 **첼시 25/26 마레스카·로즈니어 체제** 표본이다(불변규칙 7) — 알론소 실측 0경기.\u000a**[2026-08-19 3-4-2-1 뎁스 순서]** sort_order=6. 귀스토 — 네투 뒤 우측 뎁스로 이동. 백3 3경기에서 45분+ 출전이 없어 그리드가 25/26 체제 그대로다.'),6,NULL,NULL,'RM');
INSERT INTO squad_entries VALUES(72,2,38,NULL,'W','OWNED','111372113X100150001300001',NULL,NULL,NULL,'w_winger','Versatile',0.935000000000000053,'[2026-08-19] 3-4-3 전환 신규 행 · core.kernel best_fit','⭐ **[2026-08-19] 3-4-3 전환 신규 행.** 스쿼드 최고 적합 .935. ⚠️ RW .935 ↔ LW .188로 우측 전용 — 5-4-1엔 W 군이 없어 이 값을 못 썼다. 산출: `w_winger`/Versatile **0.935** (x=82, slot_type=W). ⚠️ 그리드는 **첼시 25/26 마레스카·로즈니어 체제** 표본이다(불변규칙 7) — 알론소 실측 0경기.',8,NULL,NULL,'RW');
INSERT INTO squad_entries VALUES(73,2,42,NULL,'W','OWNED','113641227X111370013400000',NULL,NULL,NULL,'w_wideplm','Build-Up',0.8850000000000000088,'[2026-08-19] 3-4-3 전환 신규 행 · core.kernel best_fit','⭐ **[2026-08-19] 3-4-3 전환 신규 행.** RW .885. 네투 뒤 우측 뎁스. ⚠️ LW .221로 좌측 불가. 산출: `w_wideplm`/Build-Up **0.885** (x=82, slot_type=W). ⚠️ 그리드는 **첼시 25/26 마레스카·로즈니어 체제** 표본이다(불변규칙 7) — 알론소 실측 0경기.',9,NULL,NULL,'RW');
INSERT INTO squad_entries VALUES(74,2,13,NULL,'W','OWNED','46465487X9347552535401121',NULL,NULL,NULL,'w_insidefwd','Roaming',0.553000000000000047,'[2026-08-19] 3-4-3 전환 신규 행 · core.kernel best_fit','⭐ **[2026-08-19] 3-4-3 전환 신규 행.** 전방 좌측. ⚠️ LW .553이 낮다 — 그럼에도 관측(소시에다드전 로저스 좌측) 재현을 택했다. 대안은 아래 confidence 참조. 산출: `w_insidefwd`/Roaming **0.553** (x=18, slot_type=W). ⚠️ 그리드는 **첼시 25/26 마레스카·로즈니어 체제** 표본이다(불변규칙 7) — 알론소 실측 0경기.',8,'Aston Villa (25/26)','⚠️ 첼시 공식전 0경기 — 그리드 전량이 빌라 시절(PL 37 · EL 12 · FA 2)이고 에메리 전술의 산물이다. 알론소 첼시에서 같은 위치를 쓴다는 근거가 아니다.','LW');
