INSERT INTO squad_entries VALUES(97,4,148,NULL,'GK','OWNED','0000000000000000111000X20',NULL,NULL,NULL,'gk_goalkeeper','Defend',0.94299999999999995,'WhoScored matchCentreData (Opta 원천) matchId=1993898 — https://www.whoscored.com/matches/1993898/live/spain-laliga-2026-2027-atletico-madrid-malaga · 이벤트 1,606건, 중괄호 균형 스캔으로 1.14MB 본문에서 추출. 좌표는 Opta 규약(x=공격 방향, y 낮음=우측)이라 소파 규약과 동일하고 변환 없이 쓴다. 그리드는 isTouch 이벤트만 사용.','[2026-08-20] ⭐⭐ **좌우 반전 정정본이다.** 최초 적재(FotMob heatmap 원천)는 **열이 좌우로 뒤집혀** 있었다. 원인: FotMob의 `cy`와 `verticalLayout.x`가 **Opta·SofaScore의 좌우 규약과 반대**인데, 최초 검증이 순환 논증이었다(FotMob `vl.x`로 「우측」을 정의하고 같은 FotMob `cy`로 확인했다). ⭐ 독립 반증 3건으로 확정: ⑴ **Opta 포지션 라벨**이 도밍게스=DR·다니 마르티네스=DL·카를로스 마르틴=MR·오르티스=ML로 내 배정과 정반대 ⑵ **줄리아노 시메오네**(알려진 우측 윙어)가 Opta y 16.2(우측)·FotMob cy 높음 ⑶ **마르코스 요렌테**(알려진 우측 자원)도 동일 패턴. ⇒ FotMob cy는 **높을수록 우측**이고, 올바른 환산은 `sofa_y = 100 − cy/68×100`이었다. 이번 정정은 그 변환을 고치는 대신 **Opta 좌표로 원천을 바꿨다**(1차 제공자이고 규약이 일치한다).',10,'Atletico Madrid',NULL,'GK');
