INSERT INTO squad_entries VALUES(109,4,162,NULL,'CM','OWNED','000240046X224420002600000',NULL,NULL,NULL,'cm_b2b','Ball-Winning',0.6610000000000000319,'WhoScored matchCentreData(Opta) matchId=1993898 — 26/27 라리가 R1 · reports/match-watch/2026-08-19-atm-malaga.md','[2026-08-21 누락 보정] ⚠️⚠️ **최초 적재에서 빠져 있었다 — 판단 오류였다.** §3의 표본 기준(45분+·히트포인트 15+)을 `squad_entries`에 적용해 33분 출전자를 제외했는데, 그 기준은 **이적 후보의 커널 적합 유효성**을 위한 것이고 `squad_entries`는 **스쿼드 명단**(툴 후보 풀)이다. 이 표에는 표본 컬럼 자체가 없고 AVL 36·CHE 35·LIV 22는 전부 전체 스쿼드다. ⇒ 표본 얕음은 **제외 사유가 아니라 캐비앗**으로 다룬다. ⚠️ **표본 33분·터치 24로 얕다**(평점 7.87) — 적합 0.661는 참고값이고 R2 이후 누적 표본으로 재산출한다. ⚠️ 61분 이후 포메이션이 4-4-2로 바뀌어 4-1-4-1 슬롯 배정은 근사다.',11,'Atletico Madrid',NULL,'RCM');
