INSERT INTO squad_entries VALUES(128,1,90,'완비사카','FB','CONFIRMED','000140002X001290003900234',6.589999999999999858,'full2526','25/26 웨스트햄 클럽 공식전(PL+FA컵) 45분+·히트포인트 15+ 25경기 2149분 균등가중','fb_att_wb','Support',0.93200000000000005,'transfer_targets id=147 RB 승격 (2026-08-21 21시) · avfc.co.uk 공식 2026-08-21 (구단 발표) https://www.avfc.co.uk/news/2026/august/21/signing-villa-announce-wan-bissaka-signing/ ; 실측 SofaScore player 863653 (2026-08-13 수집) ; FotMob player 760320','⚠️ 그리드는 **웨스트햄 25/26** 실측이다(불변규칙 7 — 빌라 축 실측 아님). 좌우 혼입 없음: 25/25 전 경기 우측 우세, 우2컬럼 평균 91.7%(최저 71.2%). ⛔ 이적료는 구단 미공표 — 「£18m」은 7회차 연속 1티어 미확인이라 기록하지 않는다. 의무매입 발동 조건도 미공개.',24,'West Ham United','25/26 웨스트햄(강등 시즌) 실측 · 빌라 체제 표본 0',NULL);
